// The calls of `c99_to_tac` that the Python unit tests make and that
// reach lines of c99_to_tac.py, builtin_functions.py, and fp_arith.py
// that no call of the corpus reaches, each with the TAC program the
// Python function returned and the changes it made to the c99 program
// and the tables. They were recorded by wrapping
// `Translator.translate_program` while the whole suite ran, which made
// 2829 distinct calls, and a line trace of the three modules
// over the corpus and over those calls found 253 lines that only
// the unit tests reach. These 50 calls reach all of them: the
// <stdbit.h> loops and their folding, the packed BCD builtins, the
// bit-precise conversions to and from the floating types, the casts of
// floating constants, the unions initialized by a designator, `++` and
// `--` of a `bool`, and the misplaced `[[c6502::save_hardware_stack]]`.
#include <exception>
#include <string>
#include <string_view>

#include "c99_to_tac_stage.h"
#include "capture.h"
#include "doctest.h"
#include "errors.h"
#include "json.h"
#include "stage_case.h"

namespace {

// Runs `c99_to_tac` on the c99 program `input` with the call's
// arguments, and checks that it throws the exception `output` records,
// `exception: <Python type>: <message>`.
void check_c99_to_tac_error(std::string_view args_json, std::string_view input,
                            std::string_view output) {
  c6502::capture::Call call;
  call.pass = "c99_to_tac";
  call.args_json = std::string(args_json);
  call.input = std::string(input);
  const c6502::json::Value args = c6502::json::parse(args_json);
  std::string got = "no exception\n";
  try {
    c6502::c99_to_tac::run_c99_to_tac(call, c6502::passes::AsmContext{}, *args.get("args"),
                                      *args.get("kwargs"));
  } catch (const c6502::CompileError& e) {
    got = "exception: " + e.python_type() + ": " + e.what() + "\n";
  }
  CHECK(got == output);
}

}  // namespace

